-- =====================================================================================
-- Mock dispensing + health trend data, Oct 5 - Nov 3 2026, for the Predictive Medicine Demand forecast.
-- Replaces the Mon-Fri shaped mock rows of seed_predictive_demand_mock_oct2026.sql (VMOCK-% / DMOCK-%) dated
-- from Oct 5 with a randomised profile: daily volume peaks and lows fall on random days (not Monday-high /
-- Friday-low), medicines follow illness waves (fever, headache, dizziness, body pain, GI), Sunday is closed.
--   - 374 consultation dispensations (DNOV-*) on 532 clinic visits (VNOV-*), 158 of them visits
--     without medicine (cough, sore throat, runny nose, asthma ... rising late October) for the Health Trends chart
--   - 26 direct dispensations (DDNOV-*)
-- Stock is NOT changed. Generated by a seeded script, so the numbers are the same every run.
-- Safe to re-run: deletes its own VNOV-% / DNOV-% / DDNOV-% rows first, plus the VMOCK-% / DMOCK-% rows
-- from Oct 5 (running seed_predictive_demand_mock_oct2026.sql again brings those back).
-- Run with: mysql --default-character-set=utf8mb4 -u root -p < seed_nov_2026_forecast_mock.sql
-- =====================================================================================

USE ClinicManagementSystem;
SET time_zone = '+08:00';
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

DELETE FROM consultation_dispensation WHERE consultation_dispense_id LIKE 'DNOV-%'
   OR (consultation_dispense_id LIKE 'DMOCK-%' AND dispensed_at >= '2026-10-05 00:00:00');
DELETE FROM direct_dispensation WHERE direct_dispense_id LIKE 'DDNOV-%';
DELETE FROM clinic_visits WHERE visit_id LIKE 'VNOV-%'
   OR (visit_id LIKE 'VMOCK-%' AND visit_date >= '2026-10-05');




COMMIT;
